-- ----------------------------
-- Table structure for promotion_combination_record
-- ----------------------------
DROP TABLE IF EXISTS `promotion_combination_record`;
CREATE TABLE `promotion_combination_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号，主键自增',
  `activity_id` bigint NOT NULL COMMENT '拼团活动编号',
  `combination_price` int NOT NULL COMMENT '拼团商品单价',
  `spu_id` bigint NOT NULL COMMENT 'SPU 编号',
  `spu_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '商品名字',
  `pic_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品图片',
  `sku_id` bigint NULL DEFAULT NULL COMMENT 'SKU 编号',
  `count` int NOT NULL COMMENT '购买的商品数量',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `nickname` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户昵称',
  `avatar` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户头像',
  `head_id` bigint NOT NULL COMMENT '团长编号',
  `status` tinyint NOT NULL COMMENT '开团状态',
  `order_id` bigint NULL DEFAULT NULL COMMENT '订单编号',
  `user_size` int NOT NULL COMMENT '开团需要人数',
  `user_count` int NOT NULL COMMENT '已加入拼团人数',
  `virtual_group` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否虚拟成团',
  `expire_time` datetime NULL DEFAULT NULL COMMENT '过期时间',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `tenant_id` bigint NOT NULL COMMENT '租户编号',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_activity_id`(`activity_id` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_head_id`(`head_id` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_order_id`(`order_id` ASC) USING BTREE,
  INDEX `idx_tenant_id`(`tenant_id` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '拼团记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for promotion_coupon
-- ----------------------------
DROP TABLE IF EXISTS `promotion_coupon`;
CREATE TABLE `promotion_coupon`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '优惠劵编号',
  `template_id` bigint NOT NULL COMMENT '优惠劵模板编号，关联 coupon_template 表',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '优惠劵名，冗余 coupon_template 的名称',
  `status` int NOT NULL COMMENT '优惠码状态，枚举 CouponStatusEnum',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户编号，关联 member_user 表',
  `take_type` int NULL DEFAULT NULL COMMENT '领取类型，枚举 CouponTakeTypeEnum',
  `use_price` int NULL DEFAULT NULL COMMENT '满多少金额可用（单位：分），冗余 coupon_template.use_price',
  `valid_start_time` datetime NULL DEFAULT NULL COMMENT '生效开始时间',
  `valid_end_time` datetime NULL DEFAULT NULL COMMENT '生效结束时间',
  `product_scope` int NULL DEFAULT NULL COMMENT '商品范围，枚举 PromotionProductScopeEnum',
  `product_scope_values` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '商品范围编号数组（JSON 格式），冗余 coupon_template.product_scope_values',
  `discount_type` int NULL DEFAULT NULL COMMENT '折扣类型，冗余 coupon_template.discount_type',
  `discount_percent` int NULL DEFAULT NULL COMMENT '折扣百分比，冗余 coupon_template.discount_percent',
  `discount_price` int NULL DEFAULT NULL COMMENT '优惠金额（单位：分），冗余 coupon_template.discount_price',
  `discount_limit_price` int NULL DEFAULT NULL COMMENT '折扣上限（单位：分），仅在折扣类型为百分比时生效',
  `use_order_id` bigint NULL DEFAULT NULL COMMENT '使用订单号',
  `use_time` datetime NULL DEFAULT NULL COMMENT '使用时间',
  `tenant_id` int NULL DEFAULT NULL COMMENT '租户编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '优惠劵表' ROW_FORMAT = Dynamic;

